    var text: String { if value is NSNull { return "Unknown" }; if let n=value as? NSNumber { if CFGetTypeID(n)==CFBooleanGetTypeID() { return n.boolValue ? "Yes" : "No" }; return n.stringValue }; return String(describing:value) }
}
