    init(_ v: [String:Any]) { id=v["id"] as? String ?? "";name=v["name"] as? String ?? id;kind=v["kind"] as? String ?? "";root=v["root"] as? String ?? "";phase=v["phase"] as? String ?? "unknown";alive=v["alive"] as? Bool;stale=v["stale"] as? Bool ?? true;updated=v["updatedAt"] as? String ?? "Unavailable";observed=v["observedAt"] as? String ?? "";age=v["ageSeconds"] as? Double;errors=v["errors"] as? [String] ?? [];metrics=(v["metrics"] as? [[String:Any]] ?? []).map { m in Field(m["id"] as? String ?? UUID().uuidString,m["label"] as? String ?? "Value",m["value"] ?? NSNull(),meaning:m["meaning"] as? String ?? "",origin:Workspace.pretty(m["origin"] ?? [:]),observed:m["observedAt"] as? String ?? "") } }
}
struct DataRow: Identifiable { let id: String; let key: String; let value: [String:Any]; init(_ v:[String:Any]){id=v["id"] as? String ?? UUID().uuidString;key=v["key"] as? String ?? id;value=v["value"] as? [String:Any] ?? v} }
