        let out=root.appendingPathComponent("stdout"),err=root.appendingPathComponent("stderr");FileManager.default.createFile(atPath:out.path,contents:nil,attributes:[.posixPermissions:0o600]);FileManager.default.createFile(atPath:err.path,contents:nil,attributes:[.posixPermissions:0o600]);let output=try FileHandle(forWritingTo:out),diagnostic=try FileHandle(forWritingTo:err);defer{try? output.close();try? diagnostic.close()}
