    func pollSession()async{guard !selectedSession.isEmpty,!polling else{return};let id=selectedSession,epoch=sessionEpoch;polling=true;defer{polling=false};if let r=await request("session-poll",["id":id,"offset":sessionOffset]),id==selectedSession,epoch==sessionEpoch{sessionInfo=r["session"] as? [String:Any] ?? [:];messages.append(contentsOf:r["messages"] as? [[String:Any]] ?? []);let delta=r["events"] as? [[String:Any]] ?? [];for event in delta{if let data=event["data"] as? [String:Any],data["type"] as? String=="turn.completed",let usage=data["usage"] as? [String:Any]{for key in ["input_tokens","cached_input_tokens","output_tokens"]{if let count=usage[key] as? Int{sessionTokens[key,default:0]+=count}}}};events.append(contentsOf:delta);if events.count>2000{events.removeFirst(events.count-2000)};if messages.count>500{omittedMessages+=messages.count-500;messages.removeFirst(messages.count-500)};sessionOffset=r["offset"] as? Int ?? sessionOffset}}
